  const curve = new THREE.CatmullRomCurve3(
    rig.points,
    false,
    'centripetal'
  );
  const geometry = new THREE.TubeGeometry(curve, 40, 0.25, 16, false);
  rig.surface.geometry.dispose();
  rig.surface.geometry = geometry;

  rig.hand.position.copy(handPosition);
  rig.hand.rotation.set(0, 0, angle);

  if (rig.sign < 0) {
    rig.palm.scale.set(0.205, 0.295 * handStretch, 0.175);
