  const a = track[i - 1];
  const b = track[i];
  const c = track[i + 1];
  const d = track[i + 2];
  const dt = c.t - b.t;
  const u = THREE.MathUtils.clamp((t - b.t) / dt, 0, 1);
  const u2 = u * u;
  const u3 = u2 * u;
  const h00 = 2 * u3 - 3 * u2 + 1;
  const h10 = u3 - 2 * u2 + u;
  const h01 = -2 * u3 + 3 * u2;
  const h11 = u3 - u2;

  for (const field of poseFields) {
    const p0 = a[field];
    const p1 = b[field];
    const p2 = c[field];
    const p3 = d[field];
    const m1 = (p2 - p0) / (c.t - a.t);
    const m2 = (p3 - p1) / (d.t - b.t);

    pose[field] =
      h00 * p1 +
      h10 * dt * m1 +
      h01 * p2 +
